window.MG_LAZY_DATA["data/lazy/owner-courses/a032-1a573be046b9c7c9.json"]={sha256:"1a573be046b9c7c90a921e40d2b29c2474bc03c1d33d113c1528bf45cefc28eb",value:{"id":"a032","title":"光阻烘烤與顯影控制","titleEn":"Photoresist bake and development control","category":"semiconductor","kind":"course","summary":"以 4 階段、24 個工程工作包拆解軟烤、酸擴散、溶解與輪廓，完成圖解、對照、敏感度分析、故障判別、量測規劃與驗收。","summaryEn":"Four stages and 24 work packages explore softbake, acid diffusion, dissolution and profiles through diagrams, comparisons, sensitivity studies, fault diagnosis, measurement plans and acceptance reviews.","sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid","v3-media-80679a241086"],"status":"guided","contentStatus":"reviewable-educational-curriculum","curriculumVersion":8,"depth":4,"stepCount":24,"estimatedMinutes":720,"simulationOnly":true,"languageCoverage":["zh-TW","en"],"scope":"依公開原理編寫的雙語概念實作課；每步交付可審查的工程證據。24 步是學習拆解，不代表晶圓廠的完整配方。自行設定的數值須標為假設。題目不含可直接操作的化學混配、設備設定或量產公差；照片與外部影片為代表媒體，不是假稱每步實拍。","scopeEn":"Bilingual conceptual exercises based on public principles, with reviewable evidence at each step. The 24 steps are a learning decomposition, not a complete fab recipe. Chosen numerical inputs must be labeled hypothetical. No directly operable chemical mixtures, equipment settings or production tolerances are supplied. Photos and external videos are representative media, not claimed as recordings of every step.","diagram":{"type":"wafer","labels":["烘烤機制","曝光後反應","顯影傳輸","圖案驗收"],"labelsEn":["Bake mechanisms","Post-exposure reaction","Development transport","Pattern acceptance"],"original":true,"notToScale":true},"stages":[{"id":"a032-stage01","order":1,"title":"烘烤機制","titleEn":"Bake mechanisms","description":"在「烘烤機制」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for bake mechanisms, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a032-v8-01","order":1,"sequence":1,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":[],"title":"軟烤與 PEB","titleEn":"Separate softbake and PEB","objective":"完成「軟烤與 PEB」的因果圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for separate softbake and peb, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：軟烤與 PEB。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：除溶劑與曝光後反應是不同功能。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate softbake and PEB. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Solvent removal and post-exposure reaction serve different functions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「除溶劑與曝光後反應是不同功能。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Solvent removal and post-exposure reaction serve different functions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「軟烤與 PEB」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for separate softbake and peb and add discriminating evidence.","check":"交付「軟烤與 PEB」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for separate softbake and peb: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a032-v8-01-k1","title":"軟烤與 PEB的原理","titleEn":"Separate softbake and PEB principle","text":"除溶劑與曝光後反應是不同功能。","textEn":"Solvent removal and post-exposure reaction serve different functions."},{"id":"a032-v8-01-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「軟烤與 PEB」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate softbake and peb?","options":["除溶劑與曝光後反應是不同功能。","相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Solvent removal and post-exposure reaction serve different functions.","Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step."],"answer":0,"explanation":"除溶劑與曝光後反應是不同功能。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Solvent removal and post-exposure reaction serve different functions. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}},{"id":"a032-v8-02","order":2,"sequence":2,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-01"],"title":"熱板與片溫","titleEn":"Separate hotplate and wafer temperature","objective":"完成「熱板與片溫」的對照表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for separate hotplate and wafer temperature, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：熱板與片溫。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：設定溫度不能等同於光阻瞬間溫度。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate hotplate and wafer temperature. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Setpoint does not equal instantaneous resist temperature. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「設定溫度不能等同於光阻瞬間溫度。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Setpoint does not equal instantaneous resist temperature. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「熱板與片溫」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for separate hotplate and wafer temperature and add discriminating evidence.","check":"交付「熱板與片溫」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for separate hotplate and wafer temperature: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a032-v8-02-k1","title":"熱板與片溫的原理","titleEn":"Separate hotplate and wafer temperature principle","text":"設定溫度不能等同於光阻瞬間溫度。","textEn":"Setpoint does not equal instantaneous resist temperature."},{"id":"a032-v8-02-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「熱板與片溫」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate hotplate and wafer temperature?","options":["相同最終轉速一定得到相同膜厚分布。","設定溫度不能等同於光阻瞬間溫度。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Setpoint does not equal instantaneous resist temperature.","Softbake and PEB are the same chemical step."],"answer":1,"explanation":"設定溫度不能等同於光阻瞬間溫度。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Setpoint does not equal instantaneous resist temperature. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}},{"id":"a032-v8-03","order":3,"sequence":3,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-02"],"title":"殘留溶劑","titleEn":"Assess residual solvent","objective":"完成「殘留溶劑」的敏感度草圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess residual solvent, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：殘留溶劑。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：溶劑殘留會影響顯影與材料力學行為。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess residual solvent. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Residual solvent affects development and mechanical behavior. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「溶劑殘留會影響顯影與材料力學行為。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Residual solvent affects development and mechanical behavior. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「殘留溶劑」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assess residual solvent and add discriminating evidence.","check":"交付「殘留溶劑」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess residual solvent: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a032-v8-03-k1","title":"殘留溶劑的原理","titleEn":"Assess residual solvent principle","text":"溶劑殘留會影響顯影與材料力學行為。","textEn":"Residual solvent affects development and mechanical behavior."},{"id":"a032-v8-03-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「殘留溶劑」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess residual solvent?","options":["相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。","溶劑殘留會影響顯影與材料力學行為。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step.","Residual solvent affects development and mechanical behavior."],"answer":2,"explanation":"溶劑殘留會影響顯影與材料力學行為。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Residual solvent affects development and mechanical behavior. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}},{"id":"a032-v8-04","order":4,"sequence":4,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-03"],"title":"接觸熱阻","titleEn":"Assess thermal contact","objective":"完成「接觸熱阻」的故障判別表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for assess thermal contact, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：接觸熱阻。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：晶圓翹曲與背面污染會改變熱接觸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess thermal contact. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Wafer bow and backside contamination alter thermal contact. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「晶圓翹曲與背面污染會改變熱接觸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Wafer bow and backside contamination alter thermal contact. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「接觸熱阻」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for assess thermal contact and add discriminating evidence.","check":"交付「接觸熱阻」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for assess thermal contact: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a032-v8-04-k1","title":"接觸熱阻的原理","titleEn":"Assess thermal contact principle","text":"晶圓翹曲與背面污染會改變熱接觸。","textEn":"Wafer bow and backside contamination alter thermal contact."},{"id":"a032-v8-04-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「接觸熱阻」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess thermal contact?","options":["晶圓翹曲與背面污染會改變熱接觸。","相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Wafer bow and backside contamination alter thermal contact.","Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step."],"answer":0,"explanation":"晶圓翹曲與背面污染會改變熱接觸。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Wafer bow and backside contamination alter thermal contact. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}},{"id":"a032-v8-05","order":5,"sequence":5,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-04"],"title":"升溫與冷卻","titleEn":"Include heating and cooling","objective":"完成「升溫與冷卻」的量測規劃，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for include heating and cooling, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：升溫與冷卻。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：化學反應不一定只發生在名義保溫時間內。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Include heating and cooling. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Chemical reaction need not occur only during nominal dwell. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「化學反應不一定只發生在名義保溫時間內。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Chemical reaction need not occur only during nominal dwell. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「升溫與冷卻」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for include heating and cooling and add discriminating evidence.","check":"交付「升溫與冷卻」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for include heating and cooling: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a032-v8-05-k1","title":"升溫與冷卻的原理","titleEn":"Include heating and cooling principle","text":"化學反應不一定只發生在名義保溫時間內。","textEn":"Chemical reaction need not occur only during nominal dwell."},{"id":"a032-v8-05-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「升溫與冷卻」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating include heating and cooling?","options":["相同最終轉速一定得到相同膜厚分布。","化學反應不一定只發生在名義保溫時間內。","軟烤與 PEB 可視為相同化學步驟。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Chemical reaction need not occur only during nominal dwell.","Softbake and PEB are the same chemical step."],"answer":1,"explanation":"化學反應不一定只發生在名義保溫時間內。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Chemical reaction need not occur only during nominal dwell. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}},{"id":"a032-v8-06","order":6,"sequence":6,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-05"],"title":"烘烤均勻性","titleEn":"Map bake uniformity","objective":"完成「烘烤均勻性」的工程驗收單，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for map bake uniformity, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：烘烤均勻性。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：微小溫差可能經反應敏感度放大為尺寸差。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Map bake uniformity. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Small temperature differences can amplify into dimensional variation. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「微小溫差可能經反應敏感度放大為尺寸差。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Small temperature differences can amplify into dimensional variation. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：相同最終轉速一定得到相同膜厚分布。 應回到「烘烤均勻性」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal final spin speed always gives equal thickness maps. Revisit assumptions and sampling for map bake uniformity and add discriminating evidence.","check":"交付「烘烤均勻性」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for map bake uniformity: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a032-v8-06-k1","title":"烘烤均勻性的原理","titleEn":"Map bake uniformity principle","text":"微小溫差可能經反應敏感度放大為尺寸差。","textEn":"Small temperature differences can amplify into dimensional variation."},{"id":"a032-v8-06-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","textEn":"Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}],"quiz":{"question":"評估「烘烤均勻性」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating map bake uniformity?","options":["相同最終轉速一定得到相同膜厚分布。","軟烤與 PEB 可視為相同化學步驟。","微小溫差可能經反應敏感度放大為尺寸差。"],"optionsEn":["Equal final spin speed always gives equal thickness maps.","Softbake and PEB are the same chemical step.","Small temperature differences can amplify into dimensional variation."],"answer":2,"explanation":"微小溫差可能經反應敏感度放大為尺寸差。 軟烤調整溶劑與薄膜狀態，PEB 驅動曝光後反應；兩者的合格結果應以各自的物理目的定義。","explanationEn":"Small temperature differences can amplify into dimensional variation. Softbake adjusts solvent and film state while PEB drives post-exposure reaction; accept each against its own physical purpose."}}]},{"id":"a032-stage02","order":2,"title":"曝光後反應","titleEn":"Post-exposure reaction","description":"在「曝光後反應」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for post-exposure reaction, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a032-v8-07","order":1,"sequence":7,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-06"],"title":"曝光後等待","titleEn":"Track post-exposure delay","objective":"完成「曝光後等待」的因果圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for track post-exposure delay, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：曝光後等待。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：等待時間會改變酸遷移及污染中和機會。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Track post-exposure delay. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Delay changes acid transport and opportunities for contaminant neutralization. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「等待時間會改變酸遷移及污染中和機會。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Delay changes acid transport and opportunities for contaminant neutralization. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「曝光後等待」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for track post-exposure delay and add discriminating evidence.","check":"交付「曝光後等待」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for track post-exposure delay: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a032-v8-07-k1","title":"曝光後等待的原理","titleEn":"Track post-exposure delay principle","text":"等待時間會改變酸遷移及污染中和機會。","textEn":"Delay changes acid transport and opportunities for contaminant neutralization."},{"id":"a032-v8-07-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「曝光後等待」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating track post-exposure delay?","options":["等待時間會改變酸遷移及污染中和機會。","曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Delay changes acid transport and opportunities for contaminant neutralization.","Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum."],"answer":0,"explanation":"等待時間會改變酸遷移及污染中和機會。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Delay changes acid transport and opportunities for contaminant neutralization. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}},{"id":"a032-v8-08","order":2,"sequence":8,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-07"],"title":"化學放大反應","titleEn":"Trace chemical amplification","objective":"完成「化學放大反應」的對照表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for trace chemical amplification, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：化學放大反應。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：光生酸可催化多次反應而非只對應單一光子事件。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Trace chemical amplification. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Photoacid can catalyze multiple reactions rather than one event per photon. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「光生酸可催化多次反應而非只對應單一光子事件。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Photoacid can catalyze multiple reactions rather than one event per photon. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「化學放大反應」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for trace chemical amplification and add discriminating evidence.","check":"交付「化學放大反應」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for trace chemical amplification: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a032-v8-08-k1","title":"化學放大反應的原理","titleEn":"Trace chemical amplification principle","text":"光生酸可催化多次反應而非只對應單一光子事件。","textEn":"Photoacid can catalyze multiple reactions rather than one event per photon."},{"id":"a032-v8-08-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「化學放大反應」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating trace chemical amplification?","options":["曝光劑量相同就能排除所有尺寸差。","光生酸可催化多次反應而非只對應單一光子事件。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Equal dose rules out every dimensional difference.","Photoacid can catalyze multiple reactions rather than one event per photon.","A top-view opening proves no bottom scum."],"answer":1,"explanation":"光生酸可催化多次反應而非只對應單一光子事件。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Photoacid can catalyze multiple reactions rather than one event per photon. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}},{"id":"a032-v8-09","order":3,"sequence":9,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-08"],"title":"酸擴散長度","titleEn":"Assess acid diffusion length","objective":"完成「酸擴散長度」的敏感度草圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess acid diffusion length, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：酸擴散長度。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：更長反應時間也可能增加影像模糊。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。 自訂一維擴散模型 L=√(2Dt)，固定 D 且時間增加四倍；求 L 的比例，再說明實際 PEB 中反應及淬熄為何使此模型不完整。","instructionEn":"Question for this step: Assess acid diffusion length. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Longer reaction time can also increase image blur. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs. Hypothetical 1D diffusion L=√(2Dt): hold D fixed and quadruple time. Find the L ratio and explain why reaction and quenching make this incomplete for actual PEB.","observation":"檢查結果是否能支持「更長反應時間也可能增加影像模糊。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Longer reaction time can also increase image blur. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「酸擴散長度」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for assess acid diffusion length and add discriminating evidence.","check":"交付「酸擴散長度」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。 同時交付算例的中間步驟或比較圖，並標示假設與模型限制。","checkEn":"Submit the sensitivity sketch for assess acid diffusion length: Include variables, units or dimensionless definitions, three hypothetical points and validity limits. Also submit intermediate calculations or comparison diagrams with assumptions and model limits.","knowledge":[{"id":"a032-v8-09-k1","title":"酸擴散長度的原理","titleEn":"Assess acid diffusion length principle","text":"更長反應時間也可能增加影像模糊。","textEn":"Longer reaction time can also increase image blur."},{"id":"a032-v8-09-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「酸擴散長度」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess acid diffusion length?","options":["曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。","更長反應時間也可能增加影像模糊。"],"optionsEn":["Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum.","Longer reaction time can also increase image blur."],"answer":2,"explanation":"更長反應時間也可能增加影像模糊。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Longer reaction time can also increase image blur. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}},{"id":"a032-v8-10","order":4,"sequence":10,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-09"],"title":"表面中和","titleEn":"Assess surface neutralization","objective":"完成「表面中和」的故障判別表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for assess surface neutralization, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：表面中和。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：空氣鹼性污染可能改變上表面反應。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess surface neutralization. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Airborne bases can change reactions near the top surface. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「空氣鹼性污染可能改變上表面反應。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Airborne bases can change reactions near the top surface. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「表面中和」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for assess surface neutralization and add discriminating evidence.","check":"交付「表面中和」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for assess surface neutralization: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a032-v8-10-k1","title":"表面中和的原理","titleEn":"Assess surface neutralization principle","text":"空氣鹼性污染可能改變上表面反應。","textEn":"Airborne bases can change reactions near the top surface."},{"id":"a032-v8-10-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「表面中和」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess surface neutralization?","options":["空氣鹼性污染可能改變上表面反應。","曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Airborne bases can change reactions near the top surface.","Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum."],"answer":0,"explanation":"空氣鹼性污染可能改變上表面反應。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Airborne bases can change reactions near the top surface. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}},{"id":"a032-v8-11","order":5,"sequence":11,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-10"],"title":"基底界面反應","titleEn":"Inspect substrate-interface reaction","objective":"完成「基底界面反應」的量測規劃，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for inspect substrate-interface reaction, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：基底界面反應。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：底層化學狀態會影響底部光阻輪廓。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Inspect substrate-interface reaction. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Underlying chemistry affects the resist profile near the bottom. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「底層化學狀態會影響底部光阻輪廓。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Underlying chemistry affects the resist profile near the bottom. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「基底界面反應」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for inspect substrate-interface reaction and add discriminating evidence.","check":"交付「基底界面反應」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for inspect substrate-interface reaction: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a032-v8-11-k1","title":"基底界面反應的原理","titleEn":"Inspect substrate-interface reaction principle","text":"底層化學狀態會影響底部光阻輪廓。","textEn":"Underlying chemistry affects the resist profile near the bottom."},{"id":"a032-v8-11-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「基底界面反應」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating inspect substrate-interface reaction?","options":["曝光劑量相同就能排除所有尺寸差。","底層化學狀態會影響底部光阻輪廓。","頂視開口就證明孔底完全沒有殘膠。"],"optionsEn":["Equal dose rules out every dimensional difference.","Underlying chemistry affects the resist profile near the bottom.","A top-view opening proves no bottom scum."],"answer":1,"explanation":"底層化學狀態會影響底部光阻輪廓。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Underlying chemistry affects the resist profile near the bottom. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}},{"id":"a032-v8-12","order":6,"sequence":12,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-11"],"title":"PEB 視窗","titleEn":"Build a PEB window","objective":"完成「PEB 視窗」的工程驗收單，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for build a peb window, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：PEB 視窗。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：反應完成度、尺寸及粗糙度需共同取捨。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Build a PEB window. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Reaction completion, dimensions and roughness need joint tradeoffs. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「反應完成度、尺寸及粗糙度需共同取捨。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Reaction completion, dimensions and roughness need joint tradeoffs. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：曝光劑量相同就能排除所有尺寸差。 應回到「PEB 視窗」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Equal dose rules out every dimensional difference. Revisit assumptions and sampling for build a peb window and add discriminating evidence.","check":"交付「PEB 視窗」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for build a peb window: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a032-v8-12-k1","title":"PEB 視窗的原理","titleEn":"Build a PEB window principle","text":"反應完成度、尺寸及粗糙度需共同取捨。","textEn":"Reaction completion, dimensions and roughness need joint tradeoffs."},{"id":"a032-v8-12-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","textEn":"Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}],"quiz":{"question":"評估「PEB 視窗」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating build a peb window?","options":["曝光劑量相同就能排除所有尺寸差。","頂視開口就證明孔底完全沒有殘膠。","反應完成度、尺寸及粗糙度需共同取捨。"],"optionsEn":["Equal dose rules out every dimensional difference.","A top-view opening proves no bottom scum.","Reaction completion, dimensions and roughness need joint tradeoffs."],"answer":2,"explanation":"反應完成度、尺寸及粗糙度需共同取捨。 酸催化與酸擴散同時發生，較完全的去保護可能伴隨較大的影像模糊，需要聯合量測。","explanationEn":"Reaction completion, dimensions and roughness need joint tradeoffs. Acid catalysis and diffusion occur together; more complete deprotection can accompany more blur, requiring joint measurements."}}]},{"id":"a032-stage03","order":3,"title":"顯影傳輸","titleEn":"Development transport","description":"在「顯影傳輸」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for development transport, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a032-v8-13","order":1,"sequence":13,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-12"],"title":"正負型溶解","titleEn":"Separate positive and negative tone","objective":"完成「正負型溶解」的因果圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for separate positive and negative tone, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：正負型溶解。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：顯影保留區由材料反應與顯影化學共同決定。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Separate positive and negative tone. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: Remaining regions depend on both resist chemistry and developer. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「顯影保留區由材料反應與顯影化學共同決定。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Remaining regions depend on both resist chemistry and developer. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「正負型溶解」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for separate positive and negative tone and add discriminating evidence.","check":"交付「正負型溶解」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for separate positive and negative tone: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a032-v8-13-k1","title":"正負型溶解的原理","titleEn":"Separate positive and negative tone principle","text":"顯影保留區由材料反應與顯影化學共同決定。","textEn":"Remaining regions depend on both resist chemistry and developer."},{"id":"a032-v8-13-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「正負型溶解」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating separate positive and negative tone?","options":["顯影保留區由材料反應與顯影化學共同決定。","較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Remaining regions depend on both resist chemistry and developer.","Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":0,"explanation":"顯影保留區由材料反應與顯影化學共同決定。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Remaining regions depend on both resist chemistry and developer. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}},{"id":"a032-v8-14","order":2,"sequence":14,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-13"],"title":"顯影液相容","titleEn":"Review developer compatibility","objective":"完成「顯影液相容」的對照表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for review developer compatibility, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：顯影液相容。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：不同光阻不能直接共用同一顯影條件。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Review developer compatibility. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Different resists cannot automatically share developer conditions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「不同光阻不能直接共用同一顯影條件。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Different resists cannot automatically share developer conditions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「顯影液相容」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for review developer compatibility and add discriminating evidence.","check":"交付「顯影液相容」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for review developer compatibility: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a032-v8-14-k1","title":"顯影液相容的原理","titleEn":"Review developer compatibility principle","text":"不同光阻不能直接共用同一顯影條件。","textEn":"Different resists cannot automatically share developer conditions."},{"id":"a032-v8-14-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「顯影液相容」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating review developer compatibility?","options":["較低劑量必定同時改善解析度與粗糙度。","不同光阻不能直接共用同一顯影條件。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Different resists cannot automatically share developer conditions.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":1,"explanation":"不同光阻不能直接共用同一顯影條件。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Different resists cannot automatically share developer conditions. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}},{"id":"a032-v8-15","order":3,"sequence":15,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-14"],"title":"溶解速率","titleEn":"Compare dissolution rates","objective":"完成「溶解速率」的敏感度草圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for compare dissolution rates, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：溶解速率。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：曝光與未曝光區速率差決定圖案對比。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Compare dissolution rates. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Rate contrast between exposed and unexposed regions determines image contrast. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「曝光與未曝光區速率差決定圖案對比。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Rate contrast between exposed and unexposed regions determines image contrast. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「溶解速率」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for compare dissolution rates and add discriminating evidence.","check":"交付「溶解速率」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for compare dissolution rates: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a032-v8-15-k1","title":"溶解速率的原理","titleEn":"Compare dissolution rates principle","text":"曝光與未曝光區速率差決定圖案對比。","textEn":"Rate contrast between exposed and unexposed regions determines image contrast."},{"id":"a032-v8-15-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「溶解速率」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating compare dissolution rates?","options":["較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。","曝光與未曝光區速率差決定圖案對比。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes.","Rate contrast between exposed and unexposed regions determines image contrast."],"answer":2,"explanation":"曝光與未曝光區速率差決定圖案對比。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Rate contrast between exposed and unexposed regions determines image contrast. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}},{"id":"a032-v8-16","order":4,"sequence":16,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-15"],"title":"液膜更新","titleEn":"Assess puddle renewal","objective":"完成「液膜更新」的故障判別表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for assess puddle renewal, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：液膜更新。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：顯影產物累積會改變局部傳輸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess puddle renewal. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Accumulated dissolution products change local transport. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「顯影產物累積會改變局部傳輸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Accumulated dissolution products change local transport. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「液膜更新」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for assess puddle renewal and add discriminating evidence.","check":"交付「液膜更新」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for assess puddle renewal: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a032-v8-16-k1","title":"液膜更新的原理","titleEn":"Assess puddle renewal principle","text":"顯影產物累積會改變局部傳輸。","textEn":"Accumulated dissolution products change local transport."},{"id":"a032-v8-16-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「液膜更新」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess puddle renewal?","options":["顯影產物累積會改變局部傳輸。","較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Accumulated dissolution products change local transport.","Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":0,"explanation":"顯影產物累積會改變局部傳輸。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Accumulated dissolution products change local transport. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}},{"id":"a032-v8-17","order":5,"sequence":17,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-16"],"title":"暗蝕損失","titleEn":"Measure dark erosion","objective":"完成「暗蝕損失」的量測規劃，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for measure dark erosion, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：暗蝕損失。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：未曝光保留區也可能在顯影中變薄。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure dark erosion. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: Unexposed retained regions can also thin during development. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「未曝光保留區也可能在顯影中變薄。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Unexposed retained regions can also thin during development. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「暗蝕損失」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for measure dark erosion and add discriminating evidence.","check":"交付「暗蝕損失」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for measure dark erosion: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a032-v8-17-k1","title":"暗蝕損失的原理","titleEn":"Measure dark erosion principle","text":"未曝光保留區也可能在顯影中變薄。","textEn":"Unexposed retained regions can also thin during development."},{"id":"a032-v8-17-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「暗蝕損失」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure dark erosion?","options":["較低劑量必定同時改善解析度與粗糙度。","未曝光保留區也可能在顯影中變薄。","平均線寬合格即可忽略橋接與缺孔。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Unexposed retained regions can also thin during development.","Acceptable mean width permits ignoring bridges and missing holes."],"answer":1,"explanation":"未曝光保留區也可能在顯影中變薄。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Unexposed retained regions can also thin during development. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}},{"id":"a032-v8-18","order":6,"sequence":18,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-17"],"title":"沖洗終止","titleEn":"Define rinse termination","objective":"完成「沖洗終止」的工程驗收單，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for define rinse termination, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：沖洗終止。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：沖洗改變反應與溶解產物移除，需納入時間線。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Define rinse termination. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Rinsing affects reaction termination and product removal and belongs in the timeline. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「沖洗改變反應與溶解產物移除，需納入時間線。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Rinsing affects reaction termination and product removal and belongs in the timeline. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：較低劑量必定同時改善解析度與粗糙度。 應回到「沖洗終止」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Lower dose must improve resolution and roughness together. Revisit assumptions and sampling for define rinse termination and add discriminating evidence.","check":"交付「沖洗終止」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for define rinse termination: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a032-v8-18-k1","title":"沖洗終止的原理","titleEn":"Define rinse termination principle","text":"沖洗改變反應與溶解產物移除，需納入時間線。","textEn":"Rinsing affects reaction termination and product removal and belongs in the timeline."},{"id":"a032-v8-18-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","textEn":"Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}],"quiz":{"question":"評估「沖洗終止」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating define rinse termination?","options":["較低劑量必定同時改善解析度與粗糙度。","平均線寬合格即可忽略橋接與缺孔。","沖洗改變反應與溶解產物移除，需納入時間線。"],"optionsEn":["Lower dose must improve resolution and roughness together.","Acceptable mean width permits ignoring bridges and missing holes.","Rinsing affects reaction termination and product removal and belongs in the timeline."],"answer":2,"explanation":"沖洗改變反應與溶解產物移除，需納入時間線。 顯影產物移除受局部傳質限制，厚膜或細孔的清除不能由平面大開口結果直接預測。","explanationEn":"Rinsing affects reaction termination and product removal and belongs in the timeline. Product removal depends on local transport, so thick-film or small-hole clearance cannot follow directly from large planar openings."}}]},{"id":"a032-stage04","order":4,"title":"圖案驗收","titleEn":"Pattern acceptance","description":"在「圖案驗收」建立六項互補證據，逐一檢查材料、幾何、物理機制與適用限制。","descriptionEn":"Build six complementary evidence items for pattern acceptance, checking materials, geometry, mechanisms and validity limits.","steps":[{"id":"a032-v8-19","order":1,"sequence":19,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-18"],"title":"底部殘膠","titleEn":"Identify scum","objective":"完成「底部殘膠」的因果圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a causal diagram for identify scum, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：底部殘膠。畫一張含作用前後狀態的原創圖；以箭頭標出本步原理中的因果關係；圈出一項仍需量測的未知量。判讀依據：上方開口不代表底部已完全清除。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Identify scum. Draw an original before/after diagram; mark the causal relationship in this step; circle one quantity still requiring measurement. Interpretation: An opening at the top does not prove complete bottom clearance. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「上方開口不代表底部已完全清除。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: An opening at the top does not prove complete bottom clearance. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「底部殘膠」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for identify scum and add discriminating evidence.","check":"交付「底部殘膠」因果圖：圖中要有邊界、輸入、輸出與一項不能僅由圖決定的量。","checkEn":"Submit the causal diagram for identify scum: Show boundaries, inputs, outputs and one quantity that the diagram alone cannot determine.","knowledge":[{"id":"a032-v8-19-k1","title":"底部殘膠的原理","titleEn":"Identify scum principle","text":"上方開口不代表底部已完全清除。","textEn":"An opening at the top does not prove complete bottom clearance."},{"id":"a032-v8-19-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「底部殘膠」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating identify scum?","options":["上方開口不代表底部已完全清除。","顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["An opening at the top does not prove complete bottom clearance.","Developer compatibility follows directly from color.","More acid diffusion can only improve patterns."],"answer":0,"explanation":"上方開口不代表底部已完全清除。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"An opening at the top does not prove complete bottom clearance. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}},{"id":"a032-v8-20","order":2,"sequence":20,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-19"],"title":"側壁角度","titleEn":"Measure sidewall angle","objective":"完成「側壁角度」的對照表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a controlled comparison for measure sidewall angle, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：側壁角度。建立兩個只改一項條件的假想案例；分開記錄可觀察差異與推測原因；說明如何用本步原理區分兩者。判讀依據：頂視尺寸相同可能有不同底部尺寸。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Measure sidewall angle. Create two hypothetical cases differing in one condition; separate observations from proposed causes; use this step’s principle to distinguish them. Interpretation: Equal top-view dimensions can hide different bottom dimensions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「頂視尺寸相同可能有不同底部尺寸。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Equal top-view dimensions can hide different bottom dimensions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「側壁角度」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for measure sidewall angle and add discriminating evidence.","check":"交付「側壁角度」對照表：交出兩案例、固定條件、預期差異及一項可能混淆因素。","checkEn":"Submit the controlled comparison for measure sidewall angle: Submit both cases, fixed conditions, predicted difference and one confounder.","knowledge":[{"id":"a032-v8-20-k1","title":"側壁角度的原理","titleEn":"Measure sidewall angle principle","text":"頂視尺寸相同可能有不同底部尺寸。","textEn":"Equal top-view dimensions can hide different bottom dimensions."},{"id":"a032-v8-20-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「側壁角度」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating measure sidewall angle?","options":["顯影液相容性可由顏色直接判斷。","頂視尺寸相同可能有不同底部尺寸。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Developer compatibility follows directly from color.","Equal top-view dimensions can hide different bottom dimensions.","More acid diffusion can only improve patterns."],"answer":1,"explanation":"頂視尺寸相同可能有不同底部尺寸。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"Equal top-view dimensions can hide different bottom dimensions. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}},{"id":"a032-v8-21","order":3,"sequence":21,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-20"],"title":"圖案倒塌","titleEn":"Assess pattern collapse","objective":"完成「圖案倒塌」的敏感度草圖，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a sensitivity sketch for assess pattern collapse, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：圖案倒塌。選出本步的一項輸入及一項輸出；以自訂低、中、高三點畫趨勢；逐點標註假設，並寫出趨勢可能失效的條件。判讀依據：高細長圖案在乾燥中可能受毛細力破壞。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Assess pattern collapse. Select one input and output for this step; sketch a hypothetical low/mid/high trend; label assumptions and state when the trend may fail. Interpretation: Slender patterns can fail under capillary forces during drying. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「高細長圖案在乾燥中可能受毛細力破壞。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Slender patterns can fail under capillary forces during drying. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「圖案倒塌」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for assess pattern collapse and add discriminating evidence.","check":"交付「圖案倒塌」敏感度草圖：圖須有變數、單位或無因次定義、三個假設點及適用範圍。","checkEn":"Submit the sensitivity sketch for assess pattern collapse: Include variables, units or dimensionless definitions, three hypothetical points and validity limits.","knowledge":[{"id":"a032-v8-21-k1","title":"圖案倒塌的原理","titleEn":"Assess pattern collapse principle","text":"高細長圖案在乾燥中可能受毛細力破壞。","textEn":"Slender patterns can fail under capillary forces during drying."},{"id":"a032-v8-21-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「圖案倒塌」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating assess pattern collapse?","options":["顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。","高細長圖案在乾燥中可能受毛細力破壞。"],"optionsEn":["Developer compatibility follows directly from color.","More acid diffusion can only improve patterns.","Slender patterns can fail under capillary forces during drying."],"answer":2,"explanation":"高細長圖案在乾燥中可能受毛細力破壞。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"Slender patterns can fail under capillary forces during drying. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}},{"id":"a032-v8-22","order":4,"sequence":22,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-21"],"title":"尺寸偏差歸因","titleEn":"Attribute CD bias","objective":"完成「尺寸偏差歸因」的故障判別表，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a fault-discrimination table for attribute cd bias, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：尺寸偏差歸因。假設本步預期結果未出現；提出兩個不同機制；為各機制選一個能支持或否定的觀察，避免只重複同一量測。判讀依據：曝光、PEB 與顯影都可能造成最終尺寸偏差。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Attribute CD bias. Assume the expected result fails; propose two distinct mechanisms; choose an observation that supports or rejects each rather than repeating one measurement. Interpretation: Exposure, PEB and development can all cause final CD bias. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「曝光、PEB 與顯影都可能造成最終尺寸偏差。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Exposure, PEB and development can all cause final CD bias. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「尺寸偏差歸因」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for attribute cd bias and add discriminating evidence.","check":"交付「尺寸偏差歸因」故障判別表：至少列出兩個假說、各自的辨別證據及先檢查順序。","checkEn":"Submit the fault-discrimination table for attribute cd bias: List two hypotheses, discriminating evidence for each and a check order.","knowledge":[{"id":"a032-v8-22-k1","title":"尺寸偏差歸因的原理","titleEn":"Attribute CD bias principle","text":"曝光、PEB 與顯影都可能造成最終尺寸偏差。","textEn":"Exposure, PEB and development can all cause final CD bias."},{"id":"a032-v8-22-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「尺寸偏差歸因」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating attribute cd bias?","options":["曝光、PEB 與顯影都可能造成最終尺寸偏差。","顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Exposure, PEB and development can all cause final CD bias.","Developer compatibility follows directly from color.","More acid diffusion can only improve patterns."],"answer":0,"explanation":"曝光、PEB 與顯影都可能造成最終尺寸偏差。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"Exposure, PEB and development can all cause final CD bias. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}},{"id":"a032-v8-23","order":5,"sequence":23,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-22"],"title":"曝光烘烤矩陣","titleEn":"Design a dose-bake matrix","objective":"完成「曝光烘烤矩陣」的量測規劃，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a measurement plan for design a dose-bake matrix, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：曝光烘烤矩陣。針對本步定義待測量及採樣位置；列出解析度、背景與重複性；設計一個見證或空白，並說明檢出限如何限制結論。判讀依據：交叉實驗可辨識劑量與熱歷程交互作用。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Design a dose-bake matrix. Define the measurand and sampling locations; list resolution, background and repeatability; design a witness or blank and explain detection-limit constraints. Interpretation: A crossed study can identify dose-thermal-history interactions. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「交叉實驗可辨識劑量與熱歷程交互作用。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: A crossed study can identify dose-thermal-history interactions. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「曝光烘烤矩陣」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for design a dose-bake matrix and add discriminating evidence.","check":"交付「曝光烘烤矩陣」量測規劃：提供採樣座標、量測單位、對照與不確定度來源。","checkEn":"Submit the measurement plan for design a dose-bake matrix: Provide sampling coordinates, units, controls and uncertainty sources.","knowledge":[{"id":"a032-v8-23-k1","title":"曝光烘烤矩陣的原理","titleEn":"Design a dose-bake matrix principle","text":"交叉實驗可辨識劑量與熱歷程交互作用。","textEn":"A crossed study can identify dose-thermal-history interactions."},{"id":"a032-v8-23-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「曝光烘烤矩陣」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating design a dose-bake matrix?","options":["顯影液相容性可由顏色直接判斷。","交叉實驗可辨識劑量與熱歷程交互作用。","增加酸擴散永遠只會改善圖案。"],"optionsEn":["Developer compatibility follows directly from color.","A crossed study can identify dose-thermal-history interactions.","More acid diffusion can only improve patterns."],"answer":1,"explanation":"交叉實驗可辨識劑量與熱歷程交互作用。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"A crossed study can identify dose-thermal-history interactions. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}},{"id":"a032-v8-24","order":6,"sequence":24,"estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v8a-softbake","v8a-peb","v8a-develop","v8a-acid"],"prerequisiteIds":["a032-v8-23"],"title":"光阻圖案交接","titleEn":"Release the resist pattern","objective":"完成「光阻圖案交接」的工程驗收單，把軟烤、酸擴散、溶解與輪廓中的相關限制連到可觀察證據。","objectiveEn":"Complete a engineering acceptance sheet for release the resist pattern, connecting relevant limits in softbake, acid diffusion, dissolution and profiles to observable evidence.","instruction":"本步問題：光阻圖案交接。整合本步及本階段先前證據；提出兩項彼此不同的接受條件；再列一個會讓你暫緩放行的結果及下一個確認動作。判讀依據：線寬、輪廓、殘膠及薄膜損失需共同符合要求。引用列出的原始資料；若使用數值，清楚標成自訂教學假設。","instructionEn":"Question for this step: Release the resist pattern. Combine this step with earlier stage evidence; propose two independent acceptance criteria; name one hold condition and the next confirming action. Interpretation: Width, profile, scum and retained-film loss must jointly meet requirements. Cite the listed primary material; label any chosen numbers as hypothetical educational inputs.","observation":"檢查結果是否能支持「線寬、輪廓、殘膠及薄膜損失需共同符合要求。」；若證據不足，標記尚未確定並寫出缺少的量測。","observationEn":"Check whether the evidence supports: Width, profile, scum and retained-film loss must jointly meet requirements. If insufficient, mark the conclusion unresolved and name the missing measurement.","failure":"常見錯判：顯影液相容性可由顏色直接判斷。 應回到「光阻圖案交接」的假設與採樣範圍，補足能區分機制的證據。","failureEn":"Common misinterpretation: Developer compatibility follows directly from color. Revisit assumptions and sampling for release the resist pattern and add discriminating evidence.","check":"交付「光阻圖案交接」工程驗收單：驗收單需有原理、兩項證據、保留疑問及前後模組交接。","checkEn":"Submit the engineering acceptance sheet for release the resist pattern: The sheet needs the principle, two evidence items, open questions and module handoff.","knowledge":[{"id":"a032-v8-24-k1","title":"光阻圖案交接的原理","titleEn":"Release the resist pattern principle","text":"線寬、輪廓、殘膠及薄膜損失需共同符合要求。","textEn":"Width, profile, scum and retained-film loss must jointly meet requirements."},{"id":"a032-v8-24-k2","title":"本階段的機制與工程權衡","titleEn":"Stage mechanisms and engineering tradeoffs","text":"尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","textEn":"CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}],"quiz":{"question":"評估「光阻圖案交接」時，哪項敘述可以採用？","questionEn":"Which statement is valid when evaluating release the resist pattern?","options":["顯影液相容性可由顏色直接判斷。","增加酸擴散永遠只會改善圖案。","線寬、輪廓、殘膠及薄膜損失需共同符合要求。"],"optionsEn":["Developer compatibility follows directly from color.","More acid diffusion can only improve patterns.","Width, profile, scum and retained-film loss must jointly meet requirements."],"answer":2,"explanation":"線寬、輪廓、殘膠及薄膜損失需共同符合要求。 尺寸、底部殘膠與側壁角是互補圖案指標；頂視 CD 合格仍可能無法完成後續蝕刻轉移。","explanationEn":"Width, profile, scum and retained-film loss must jointly meet requirements. CD, bottom scum and sidewall angle are complementary; acceptable top-view CD can still fail later etch transfer."}}]}],"subcategory":"lithography","subcategoryTitle":"光阻、光罩與微影","subcategoryTitleEn":"Resists, masks and lithography"}};
